insert into tax_templates
  (country, code, name, name_i18n, description, amount_type, amount, applies_to, treatment,
   valid_from, valid_to, legal_reference, vat_category, exemption_code, sequence,
   tax_kind, recoverable, conditions, jurisdiction, price_include, cash_basis,
   cash_basis_transition_account_code, source_key,
   applies_seller_territory, applies_buyer_territory, applies_supply_territory,
   applies_supply_vs_seller)
values
  ('TD', 'TD-P-1925', 'Achats de biens, taux normal 19,25 %', '{}'::jsonb, 'Taxe récupérable sur achats de marchandises, déductible dans les mêmes conditions que la taxe elle-même (directive CEMAC art. 22-1) : un seul montant, sans distinguer la part communale de la part étatique, faute de compte récupérable séparé au plan SYSCOHADA pour cette distinction.', 'percent', 19.25, 'purchase', 'domestic', date '2024-01-01', null, 'Code général des impôts, art. 238-I-1°, art. 1017 et loi de finances pour 2024, art. 16, pour le taux facturé de 19,25 % ; directive CEMAC n° 11/22, art. 22-1 — la surtaxe additionnelle n''est admise que si elle est déductible comme la taxe elle-même ; art. 246-II (nouveau), issu de la loi de finances pour 2026, art. 33 — « Sont également non déductibles de la TVA... les factures non électroniques normalisées, à exception des factures des fournisseurs étrangers ».', 'S', null, 110, 'vat', true, '{}'::tax_condition[], null, false, false, null, 'lf-2024', null, null, null, null),
  ('TD', 'TD-P-1925-IMMO', 'Immobilisations, taux normal 19,25 %', '{}'::jsonb, null, 'percent', 19.25, 'purchase', 'domestic', date '2024-01-01', null, 'Code général des impôts, art. 238-I-1°, art. 1017 et loi de finances pour 2024, art. 16 ; directive CEMAC n° 11/22, art. 22-1.', 'S', null, 130, 'vat', true, '{}'::tax_condition[], null, false, false, null, 'lf-2024', null, null, null, null),
  ('TD', 'TD-P-1925-SRV', 'Services extérieurs, taux normal 19,25 %', '{}'::jsonb, null, 'percent', 19.25, 'purchase', 'domestic', date '2024-01-01', null, 'Code général des impôts, art. 238-I-1°, art. 1017 et loi de finances pour 2024, art. 16 ; directive CEMAC n° 11/22, art. 22-1.', 'S', null, 120, 'vat', true, '{}'::tax_condition[], null, false, false, null, 'lf-2024', null, null, null, null),
  ('TD', 'TD-P-9', 'Achats de biens de la liste réduite, 9 %', '{}'::jsonb, null, 'percent', 9, 'purchase', 'domestic', date '2026-01-01', null, 'Code général des impôts, art. 238-I-2°, dans la rédaction de la loi de finances pour 2026, art. 32.', 'S', null, 140, 'vat', true, '{}'::tax_condition[], null, false, false, null, 'lf-2026', null, null, null, null),
  ('TD', 'TD-P-9-SRV', 'Hébergement et restauration, 9 %', '{}'::jsonb, null, 'percent', 9, 'purchase', 'domestic', date '2026-01-01', null, 'Code général des impôts, art. 238-I-2°, dans la rédaction de la loi de finances pour 2026, art. 32.', 'S', null, 150, 'vat', true, '{}'::tax_condition[], null, false, false, null, 'lf-2026', null, null, null, null),
  ('TD', 'TD-P-AUTOLIQ', 'Achat en autoliquidation, 19,25 %', '{}'::jsonb, 'TVA due par l''entreprise auprès d''un fournisseur qui ne relève pas de l''IGL, ou qui en relève mais a dépassé au cours de l''opération le seuil de 50 millions de FCFA, et qui ne la facture donc pas : la dette (compte 4478) et la créance de déduction (compte 4452) se neutralisent en écriture, chacune atteignant sa propre case de la déclaration.', 'percent', 19.25, 'purchase', 'domestic_reverse_charge', date '2026-01-01', null, 'Code général des impôts, art. 229-V (nouveau), issu de la loi de finances pour 2026, art. 30 — la taxe non facturée est « auto liquidée, collectée par l''assujetti [l''acheteur] et versée au Trésor Public dans les conditions de droit commun relatives à la TVA retenue à la source » ; « Cette TVA auto-liquidée est déductible chez l''assujetti dans les conditions de droit commun. »', 'AE', null, 160, 'vat', true, array['seller_threshold']::tax_condition[], null, false, false, null, 'lf-2026', null, null, null, null),
  ('TD', 'TD-S-1925', 'Ventes de biens, taux normal 19,25 %', '{}'::jsonb, 'Livraisons de biens au taux normal de 17,5 %, majoré des centimes communaux et provinciaux : le compte 4431 reçoit la part de l''État (90,909 % de la taxe facturée) et le compte 4422 la part des collectivités publiques (9,091 %). Un seul taux de 19,25 % appliqué une fois, jamais 17,5 % puis 10 % du résultat : deux arrondis successifs peuvent s''écarter d''une unité monétaire de l''arrondi unique que porte la facture.', 'percent', 19.25, 'sale', 'domestic', date '2024-01-01', null, 'Code général des impôts, art. 238-I-1°, dans la rédaction de la loi de finances pour 2024 (loi n° 031/PT/2023), art. 26, reconduit par la loi de finances pour 2026, art. 32 — taux de 17,5 % ; loi de finances pour 2024, art. 16, et Code général des impôts, art. 1017 — le taux facturé est porté à 19,25 % pour tenir compte des Centimes Communaux et Provinciaux ; directive CEMAC n° 11/22 du 10 novembre 2022, art. 22-1 — une surtaxe additionnelle à la taxe sur la valeur ajoutée n''est admise que si elle est déductible dans les mêmes conditions que la taxe elle-même.', 'S', null, 10, 'vat', true, '{}'::tax_condition[], null, false, false, null, 'lf-2024', null, null, null, null),
  ('TD', 'TD-S-1925-SRV', 'Prestations de services, taux normal 19,25 %', '{}'::jsonb, 'Prestations de services au taux normal, même répartition que TD-S-1925, sur le compte 4432.', 'percent', 19.25, 'sale', 'domestic', date '2024-01-01', null, 'Code général des impôts, art. 238-I-1°, dans la rédaction de la loi de finances pour 2024, art. 26, reconduit par la loi de finances pour 2026, art. 32 ; loi de finances pour 2024, art. 16, et CGI art. 1017 pour les 19,25 % facturés ; directive CEMAC n° 11/22, art. 22-1.', 'S', null, 20, 'vat', true, '{}'::tax_condition[], null, false, false, null, 'lf-2024', null, null, null, null),
  ('TD', 'TD-S-9', 'Biens de la liste réduite, 9 %', '{}'::jsonb, 'Sucre, huile, lait, yaourt, beurre, fromage, viande, savon, textile, fer à béton, produits agroalimentaires de fabrication locale hors alcool, matériel d''artisanat et de pêche.', 'percent', 9, 'sale', 'domestic', date '2026-01-01', null, 'Code général des impôts, art. 238-I-2°, dans la rédaction de la loi de finances pour 2026 (loi n° 008/AN/SENAT/2025), art. 32 — taux réduit de 9 % sur la liste qu''il énumère. Le texte ne dit rien d''une majoration par centimes additionnels sur ce taux : aucune n''est portée ici, faute de disposition trouvée qui l''établirait ou l''exclurait.', 'S', null, 30, 'vat', true, array['supply_nature']::tax_condition[], null, false, false, null, 'lf-2026', null, null, null, null),
  ('TD', 'TD-S-9-SRV', 'Hébergement et restauration, 9 %', '{}'::jsonb, null, 'percent', 9, 'sale', 'domestic', date '2026-01-01', null, 'Code général des impôts, art. 238-I-2°, dans la rédaction de la loi de finances pour 2026, art. 32 — taux réduit de 9 % sur l''hébergement et la restauration.', 'S', null, 40, 'vat', true, array['supply_nature']::tax_condition[], null, false, false, null, 'lf-2026', null, null, null, null),
  ('TD', 'TD-S-AUTOLIQ', 'Vente en autoliquidation', '{}'::jsonb, 'Vente à une personne assujettie par un vendeur qui ne relève pas de l''Impôt Général Libératoire (IGL), ou qui en relève mais a dépassé au cours de l''opération le seuil de 50 millions de FCFA : la taxe n''est pas facturée, l''acheteur assujetti l''auto-liquide.', 'percent', 0, 'sale', 'domestic_reverse_charge', date '2026-01-01', null, 'Code général des impôts, art. 229-V (nouveau), issu de la loi de finances pour 2026, art. 30 — « Lorsqu''une personne physique ou morale ne relevant pas de l''IGL, ou relevant de l''IGL mais ayant dépassé au cours d''une opération le seuil de 50 millions de FCFA, fournit une prestation de service ou vend un bien à une personne assujettie à la TVA, la TVA bien que ne figurant pas sur la facture est auto liquidée, collectée par l''assujetti et versée au Trésor Public dans les conditions de droit commun relatives à la TVA retenue à la source. »', 'AE', null, 70, 'vat', true, array['seller_threshold']::tax_condition[], null, false, false, null, 'lf-2026', null, null, null, null),
  ('TD', 'TD-S-EXO', 'Opération exonérée (art. 230)', '{}'::jsonb, null, 'percent', 0, 'sale', 'exempt', date '2026-01-01', null, 'Code général des impôts, art. 230, dans la rédaction de la loi de finances pour 2026, art. 31, dont le 15° exonère par position tarifaire les médicaments, les viandes (n° 02), les laits (n° 0401-0402), le pain, la farine, les livres scolaires, les semences, les engrais, le matériel agricole et le matériel photovoltaïque (n° 8541.42) — table vérifiée directement sur le fac-similé de la loi.', 'E', null, 60, 'vat', true, array['supply_nature']::tax_condition[], null, false, false, null, 'lf-2026', null, null, null, null),
  ('TD', 'TD-S-EXP', 'Exportation et opérations assimilées, taux zéro', '{}'::jsonb, 'Exportations, transports aériens internationaux, avitaillement en carburant Jet A1 des aéronefs à destination de l''étranger, entretien et réparation d''aéronefs.', 'percent', 0, 'sale', 'export', date '2026-01-01', null, 'Code général des impôts, art. 238-I-3°, dans la rédaction de la loi de finances pour 2026, art. 32 — taux zéro sur les exportations et les opérations qu''il énumère. La loi remplace l''article 238 en bloc (« Article 238 (nouveau) ») ; son 3° n''a pas été relu mot à mot au-delà des 1° et 2° dont le contenu a été vérifié.', 'G', null, 50, 'vat', true, array['transport_evidence']::tax_condition[], null, false, false, null, 'lf-2026', null, null, null, null)
on conflict (country, code) do update set
