insert into tax_report_templates
  (country, code, name, periods, period_default, valid_from, valid_to, legal_reference,
   is_periodic_return, deadline_rule, deadline_day, deadline_plus_days,
   deadline_reference, deadline_source_key, file_format)
values
  ('TD', 'TD-TVA', 'Déclaration de taxe sur la valeur ajoutée', array['month']::declaration_period[], 'month'::declaration_period, date '2026-01-01', null, 'Code général des impôts, art. 229-III — « Seuls, les contribuables soumis au Régime du réel normal d''imposition et ceux soumis au RSI sont autorisés à facturer la TVA de manière apparente et à la déduire. Elles sont tenues à déposer leur déclaration mensuellement sans distinction de régime. » Disposition inchangée par la loi de finances pour 2026, dont l''article 30 n''a ajouté à l''article 229 que le paragraphe V (autoliquidation) ; art. 886-IV — une déclaration néant est obligatoire en l''absence d''opération ; art. 886-III — la déclaration est accompagnée du paiement de la taxe ; art. 996 — la déclaration est télétransmise par le portail e-Tax (sigi.finances.gouv.td). Le modèle imprimé du formulaire et la numérotation de ses cases ne sont publiés dans aucune source officielle trouvée : les cases de ce fichier sont nommées d''après ce que l''article 229 fait déclarer, et non d''après un formulaire.', true,null, null, null, null, null, null)
on conflict (country, code) do update set
  name                = excluded.name,
  periods             = excluded.periods,
  period_default      = excluded.period_default,
  valid_from          = excluded.valid_from,
