values
  ('TD', 'TD-TVA', 'CA1925', 'base', 'Opérations taxables au taux normal (19,25 % facturés)', '{}'::jsonb, 10, null, '{}'::text[], '{}'::text[], null, null, false, false, null, 'Code général des impôts, art. 229-III et art. 238-I-1°', 'cgi'),
  ('TD', 'TD-TVA', 'CA9', 'base', 'Opérations taxables au taux réduit de 9 %', '{}'::jsonb, 20, null, '{}'::text[], '{}'::text[], null, null, false, false, null, 'Code général des impôts, art. 229-III et art. 238-I-2°, dans la rédaction de la loi de finances pour 2026, art. 32', 'cgi'),
  ('TD', 'TD-TVA', 'EXP', 'base', 'Exportations et opérations assimilées, taux zéro', '{}'::jsonb, 30, null, '{}'::text[], '{}'::text[], null, null, false, false, null, 'Code général des impôts, art. 229-III et art. 238-I-3°, dans la rédaction de la loi de finances pour 2026, art. 32 — la loi remplace l''article 238 en bloc (« Article 238 (nouveau) »), son 3° n''a pas été relu mot à mot au-delà des 1° et 2° cités par le pack', 'cgi'),
  ('TD', 'TD-TVA', 'EXO', 'base', 'Opérations exonérées (art. 230)', '{}'::jsonb, 40, null, '{}'::text[], '{}'::text[], null, null, false, false, null, 'Code général des impôts, art. 229-III et art. 230, dans la rédaction de la loi de finances pour 2026, art. 31', 'cgi'),
  ('TD', 'TD-TVA', 'AUTOL', 'base', 'Ventes en autoliquidation, taxe due par le client', '{}'::jsonb, 45, null, '{}'::text[], '{}'::text[], null, null, false, false, null, 'Code général des impôts, art. 229-V (nouveau), issu de la loi de finances pour 2026, art. 30 — « Lorsqu''une personne physique ou morale ne relevant pas de l''IGL, ou relevant de l''IGL mais ayant dépassé au cours d''une opération le seuil de 50 millions de FCFA, fournit une prestation de service ou vend un bien à une personne assujettie à la TVA, la TVA bien que ne figurant pas sur la facture est auto liquidée, collectée par l''assujetti et versée au Trésor Public dans les conditions de droit commun relatives à la TVA retenue à la source. » Le fait générateur tient au régime du vendeur (non affilié à l''Impôt Général Libératoire, ou l''ayant dépassé), et non à un choix libre de ne pas facturer la taxe.', 'cgi'),
  ('TD', 'TD-TVA', 'CAT', 'total', 'Montant total des opérations', '{}'::jsonb, 50, null, array['CA1925', 'CA9', 'EXP', 'EXO', 'AUTOL']::text[], '{}'::text[], null, null, false, false, null, 'Code général des impôts, art. 229-III', 'cgi'),
  ('TD', 'TD-TVA', 'TVA1925', 'tax', 'Taxe exigible, part principale du taux de 19,25 %', '{}'::jsonb, 60, null, '{}'::text[], '{}'::text[], null, null, false, false, null, 'Code général des impôts, art. 229-III, art. 238-I-1° et art. 1017 — part de la taxe facturée qui revient à l''État, 90,909 % du montant facturé à 19,25 %', 'cgi'),
  ('TD', 'TD-TVA', 'CAC1925', 'tax', 'Centimes communaux et provinciaux sur le taux de 19,25 %', '{}'::jsonb, 65, null, '{}'::text[], '{}'::text[], null, null, false, false, null, 'Loi de finances pour 2024, art. 16, et Code général des impôts, art. 1017 — part de la taxe facturée qui revient aux collectivités publiques, 9,091 % du montant facturé à 19,25 %. Déclarée avec la taxe sur une case distincte parce que la loi la garde à part des collectivités, sans qu''un formulaire officiel trouvé en fixe le numéro.', 'lf-2024'),
  ('TD', 'TD-TVA', 'TVA9', 'tax', 'Taxe exigible au taux réduit de 9 %', '{}'::jsonb, 70, null, '{}'::text[], '{}'::text[], null, null, false, false, null, 'Code général des impôts, art. 229-III et art. 238-I-2°', 'cgi'),
  ('TD', 'TD-TVA', 'TVADUE', 'tax', 'Taxe due en autoliquidation (achats)', '{}'::jsonb, 75, null, '{}'::text[], '{}'::text[], null, null, false, false, null, 'Code général des impôts, art. 229-V (nouveau), issu de la loi de finances pour 2026, art. 30 — la taxe est « collectée par l''assujetti [acheteur] et versée au Trésor Public dans les conditions de droit commun relatives à la TVA retenue à la source », soit, par renvoi, celles de l''art. 245 et de son échéance du 15 du mois suivant (loi de finances pour 2024, art. 35) ; « Cette TVA auto-liquidée est déductible chez l''assujetti dans les conditions de droit commun. »', 'cgi'),
  ('TD', 'TD-TVA', 'TVAB', 'total', 'Total de la taxe exigible', '{}'::jsonb, 80, null, array['TVA1925', 'CAC1925', 'TVA9', 'TVADUE']::text[], '{}'::text[], null, null, false, false, null, 'Code général des impôts, art. 229-III', 'cgi'),
  ('TD', 'TD-TVA', 'DEDIMMO', 'tax', 'TVA déductible sur immobilisations', '{}'::jsonb, 90, null, '{}'::text[], '{}'::text[], null, null, false, false, null, 'Code général des impôts, art. 229-III, et directive CEMAC n° 11/22, art. 22-1 pour la déductibilité de la part communale et provinciale', 'cgi'),
  ('TD', 'TD-TVA', 'DEDBS', 'tax', 'TVA déductible sur biens et services', '{}'::jsonb, 100, null, '{}'::text[], '{}'::text[], null, null, false, false, null, 'Code général des impôts, art. 229-III, et directive CEMAC n° 11/22, art. 22-1', 'cgi'),
  ('TD', 'TD-TVA', 'DEDT', 'total', 'Total des déductions', '{}'::jsonb, 110, null, array['DEDIMMO', 'DEDBS']::text[], '{}'::text[], null, null, false, false, null, 'Code général des impôts, art. 229-III', 'cgi'),
  ('TD', 'TD-TVA', 'NET', 'total', 'TVA nette à payer', '{}'::jsonb, 120, null, array['TVAB']::text[], array['DEDT']::text[], null, null, true, false, null, 'Code général des impôts, art. 229-III et art. 886-III — la déclaration est accompagnée du paiement', 'cgi'),
  ('TD', 'TD-TVA', 'CRED', 'total', 'Crédit de TVA à reporter', '{}'::jsonb, 130, null, array['DEDT']::text[], array['TVAB']::text[], null, null, true, false, null, 'Code général des impôts, art. 229-III — aucun texte trouvé ne plafonne la durée du report', 'cgi')
