update country_defaults set
  numbering_gapless             = false,
  number_format                 = '{CODE}/{YYYY}/{NNNN}',
  legal_payment_days            = null,
  late_payment_reference        = null,
  numbering_legal_reference     = 'Code général des impôts, art. 246 (mentions de la facture, dans la rédaction de la loi de finances pour 2023, art. 17-II) — la facture porte un numéro et une date. Le texte impose un numéro, jamais explicitement une continuité ni une absence de trou ; le format proposé ici le permet sans l''exiger.',
  numbering_source_key          = 'cgi',
  payment_terms_legal_reference = null,
  payment_terms_source_key      = null,
  tax_point_rule                = null,
  tax_point_legal_reference     = null,
  tax_point_source_key          = null,
  posted_edit_policy            = null,
  posted_edit_policy_legal_reference = null,
  posted_edit_policy_source_key = null,
  einvoice_profile              = null,
  einvoice_mandatory_from       = null,
  einvoice_legal_reference      = 'Loi de finances pour 2023, art. 17 ; loi de finances pour 2024, art. 43 ; loi de finances pour 2026, art. 33, modifiant l''art. 246-II du Code général des impôts — « Sont également non déductibles de la TVA... les factures non électroniques normalisées, à exception des factures des fournisseurs étrangers » : depuis le 1er janvier 2026, une facture qui n''est pas une facture électronique normalisée (FEN), délivrée par une machine certifiée reliée au système de la Direction générale des Impôts, n''ouvre plus droit à déduction, sauf lorsqu''elle émane d''un fournisseur étranger. Loi de finances pour 2026, art. 46 — liste des contribuables tenus d''émettre une FEN ; art. 71 — aucune dépense publique ne peut être engagée ni payée sur la base d''une facture qui n''est pas une FEN. C''est une condition de déduction (et, pour la dépense publique, de paiement), non une obligation générale d''échange dématérialisé entre entreprises au sens de ce champ : aucun profil technique normalisé (UBL, schéma d''échange), aucun schéma d''identifiant des parties et aucune obligation d''émission au sens strict n''ont été trouvés publiés par la DGI à la date de ce pack. Le portail fen.finances.gouv.td n''a pas été lu comme une spécification technique.',
  einvoice_source_key           = 'fen',
  party_scheme                  = null,
  vat_scheme                    = null,
  bank_statement_formats        = null,
  payment_formats               = null,
  fiscal_year_default           = 'calendar'
 where country = 'TD';

insert into legal_mention_templates
  (country, code, applies_when, text, text_i18n, sequence, valid_from, valid_to, legal_reference)
values
  ('TD', 'reverse_charge', 'reverse_charge', 'TVA due par le client — autoliquidation, article 229-V du Code général des impôts.', '{}'::jsonb, 5, date '1970-01-01', null, 'Code général des impôts, art. 229-V (nouveau), issu de la loi de finances pour 2026, art. 30 — lorsqu''un vendeur qui ne relève pas de l''Impôt Général Libératoire (IGL), ou qui en relève mais a dépassé au cours de l''opération le seuil de 50 millions de FCFA, vend à une personne assujettie, la taxe non facturée est auto-liquidée par l''acheteur.'),
  ('TD', 'exempt', 'exempt', 'Opération exonérée de la taxe sur la valeur ajoutée — article 230 du Code général des impôts.', '{}'::jsonb, 10, date '1970-01-01', null, 'Code général des impôts, art. 246 — la facture porte les mentions que le texte impose ; art. 230, dans la rédaction de la loi de finances pour 2026, art. 31, pour la liste des exonérations.'),
  ('TD', 'export', 'export', 'Exportation taxée au taux zéro — article 238-I-3° du Code général des impôts.', '{}'::jsonb, 20, date '1970-01-01', null, 'Code général des impôts, art. 238-I-3°, dans la rédaction de la loi de finances pour 2026, art. 32 — taux zéro applicable aux exportations, aux transports aériens internationaux, à l''avitaillement en carburant Jet A1 des aéronefs à destination de l''étranger et à l''entretien et à la réparation des aéronefs.')
